//! Swiss Ephemeris end-to-end golden anchors for the line engine.
//!
//! The binding verification gate for MC/IC verticals and ASC/DSC horizon
//! curves: for five fixed test instants and all twelve bodies, every line
//! must reproduce the Swiss Ephemeris 2.10.03 reference to within 0.01°
//! (≈ 1 km on the ground). The reference table
//! ([`FIXTURE_JSON`]) was generated by an independent implementation —
//! see its provenance header — sharing only the time-scale inputs with the
//! crate: both chains consume the same TT Julian day (the crate's own
//! UTC→TDB conversion) and the same ΔT values, so a disagreement isolates an
//! ephemeris or geometric implementation difference, not time-scale
//! modeling. The crate's ΔT model itself is validated separately by its own
//! fixtures.
//!
//! Independence of the geometry: the generator solves horizon crossings by
//! bisection on the dot-product altitude term `sin d sin b + cos d cos b
//! cos H = 0`, while the crate derives the same great circle from a
//! cross-product formulation — two different derivations of one circle. The
//! ephemeris inputs (apparent geocentric RA/Dec via `swe_calc`, Greenwich
//! apparent sidereal time via `swe_sidtime`) come from Swiss Ephemeris's own
//! ephemeris files and models throughout.
//!
//! The instants span the ΔT model's regimes and one lunar major standstill
//! (2006-03-22T18:00Z, |dec| = 28.72°), which stresses the horizon geometry
//! at maximum lunar declination. The gate is deliberately coarser than the
//! position layer's 1 arcsecond: line longitudes inherit Earth-rotation
//! sensitivity (0.004° per second of GAST), and the binding decision set the
//! line gate at 0.01°.

use ephemeris::lines::{lines_for, Angle};
use ephemeris::{load, EphemerisManifest, FilesystemStore, DATA_DIR_ENV};
use hifitime::Epoch;
use serde::Deserialize;

/// The checked-in Swiss Ephemeris reference table.
const FIXTURE_JSON: &str = include_str!("../fixtures/line_anchors_se.json");

/// The spec's binding line gate: 0.01°, about 1 km on the ground.
const GATE_DEG: f64 = 0.01;

/// One reference row: line scalars and horizon anchor points for one body at
/// one instant.
#[derive(Deserialize)]
struct AnchorRow {
    /// The instant in ISO-8601 UTC, e.g. `2000-01-01T12:00:00Z`.
    label: String,
    /// The crate's body-name string (`LineBody::name`).
    body: String,
    /// MC meridian longitude in degrees east.
    mc: f64,
    /// IC meridian longitude in degrees east.
    ic: f64,
    /// ASC anchors as `[longitude, latitude]` pairs sweeping 180° east of
    /// the sub-body meridian.
    asc: Vec<[f64; 2]>,
    /// DSC anchors as `[longitude, latitude]` pairs sweeping 180° west.
    dsc: Vec<[f64; 2]>,
}

/// The table: provenance header plus the rows.
#[derive(Deserialize)]
struct AnchorTable {
    generator: String,
    swisseph_version: String,
    rows: Vec<AnchorRow>,
}

/// The crate's line for a fixture body and angle.
fn line_of<'a>(
    lines: &'a [ephemeris::lines::AngularLine],
    body: &str,
    angle: Angle,
) -> &'a ephemeris::lines::AngularLine {
    lines
        .iter()
        .find(|line| line.body.name() == body && line.angle == angle)
        .unwrap_or_else(|| panic!("no {angle:?} line generated for {body}"))
}

/// The UTC instant of a fixture label in fixed ISO-8601 form.
fn epoch_from_label(label: &str) -> Epoch {
    let year: i32 = label[0..4].parse().expect("year");
    let month: u8 = label[5..7].parse().expect("month");
    let day: u8 = label[8..10].parse().expect("day");
    let hour: u8 = label[11..13].parse().expect("hour");
    let minute: u8 = label[14..16].parse().expect("minute");
    let second: u8 = label[17..19].parse().expect("second");
    Epoch::maybe_from_gregorian_utc(year, month, day, hour, minute, second, 0)
        .expect("valid fixture instant")
}

/// The signed angular difference `a − b` in degrees, wrapped to [−180, 180].
fn angle_difference_degrees(a: f64, b: f64) -> f64 {
    (a - b + 180.0).rem_euclid(360.0) - 180.0
}

/// The unit vector of a `[longitude, latitude]` pair in degrees.
fn unit_vector(lon_deg: f64, lat_deg: f64) -> [f64; 3] {
    let (lon, lat) = (lon_deg.to_radians(), lat_deg.to_radians());
    let cos_lat = lat.cos();
    [cos_lat * lon.cos(), cos_lat * lon.sin(), lat.sin()]
}

fn cross(a: [f64; 3], b: [f64; 3]) -> [f64; 3] {
    [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    ]
}

fn dot(a: [f64; 3], b: [f64; 3]) -> f64 {
    a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
}

fn norm(a: [f64; 3]) -> f64 {
    dot(a, a).sqrt()
}

/// The great-circle angle in degrees from a point to a segment's minor arc —
/// the distance to the segment's plane when the perpendicular foot lands on
/// the arc, otherwise the distance to the nearer endpoint.
fn distance_to_segment_degrees(point: [f64; 3], v1: [f64; 3], v2: [f64; 3]) -> f64 {
    let normal = cross(v1, v2);
    let normal_len = norm(normal);
    if normal_len == 0.0 {
        return degenerate_distance(point, v1, v2);
    }
    let normal = [
        normal[0] / normal_len,
        normal[1] / normal_len,
        normal[2] / normal_len,
    ];
    let offset = dot(point, normal);
    let foot_distance = offset.abs().asin();
    // The foot lies on the minor arc between v1 and v2 when its angular
    // separation from each endpoint does not exceed the endpoints' separation.
    let endpoint_separation = {
        let c = dot(v1, v2).clamp(-1.0, 1.0);
        c.acos()
    };
    let foot = [
        point[0] - offset * normal[0],
        point[1] - offset * normal[1],
        point[2] - offset * normal[2],
    ];
    let foot_len = norm(foot);
    let on_arc = foot_len > 0.0 && {
        let foot = [foot[0] / foot_len, foot[1] / foot_len, foot[2] / foot_len];
        dot(foot, v1).clamp(-1.0, 1.0).acos() <= endpoint_separation
            && dot(foot, v2).clamp(-1.0, 1.0).acos() <= endpoint_separation
    };
    if on_arc {
        foot_distance.to_degrees()
    } else {
        degenerate_distance(point, v1, v2)
    }
}

/// The angle in degrees to the nearer of two endpoints.
fn degenerate_distance(point: [f64; 3], v1: [f64; 3], v2: [f64; 3]) -> f64 {
    let d1 = dot(point, v1).clamp(-1.0, 1.0).acos();
    let d2 = dot(point, v2).clamp(-1.0, 1.0).acos();
    d1.min(d2).to_degrees()
}

/// The great-circle distance in degrees from a `[longitude, latitude]` point
/// to the sampled polyline, the minimum over its segments.
fn distance_to_polyline_degrees(lon: f64, lat: f64, points: &[[f64; 2]]) -> f64 {
    let point = unit_vector(lon, lat);
    let mut best = f64::INFINITY;
    for pair in points.windows(2) {
        let distance = distance_to_segment_degrees(
            point,
            unit_vector(pair[0][0], pair[0][1]),
            unit_vector(pair[1][0], pair[1][1]),
        );
        best = best.min(distance);
    }
    best
}

/// Loads the kernels once for the kernel-gated tests.
fn loaded_with_kernels() -> ephemeris::LoadedEphemeris {
    let manifest: EphemerisManifest =
        serde_json::from_str(include_str!("../manifest.json")).expect("manifest parses");
    let store = FilesystemStore::from_env().expect("data dir present");
    load(&store, &manifest).expect("kernels load and verify")
}

/// MC and IC meridians reproduce the Swiss Ephemeris longitudes.
#[test]
fn mc_ic_verticals_match_the_swisseph_anchors() {
    if std::env::var_os(DATA_DIR_ENV).is_none() {
        eprintln!("skipping: {DATA_DIR_ENV} is unset, so the real kernels are not available");
        return;
    }
    let table: AnchorTable = serde_json::from_str(FIXTURE_JSON).expect("table parses");
    assert_eq!(
        table.swisseph_version, "2.10.03",
        "the fixture must be the pinned Swiss Ephemeris version"
    );
    assert!(
        !table.generator.is_empty(),
        "the fixture must record its generator"
    );

    let loaded = loaded_with_kernels();
    let mut checked = 0;
    for row in &table.rows {
        let utc = epoch_from_label(&row.label);
        let lines = lines_for(&loaded, utc).expect("lines for fixture instant");
        for (angle, reference) in [(Angle::Mc, row.mc), (Angle::Ic, row.ic)] {
            let line = line_of(&lines, &row.body, angle);
            let computed = line.points[0].0;
            let delta = angle_difference_degrees(computed, reference);
            assert!(
                delta.abs() <= GATE_DEG,
                "{} for {} at {}: crate {computed:.9}° vs swisseph {reference:.9}°, \
                 delta {delta:.9}° > {GATE_DEG}°",
                angle.name(),
                row.body,
                row.label
            );
            checked += 1;
        }
    }
    assert_eq!(checked, 120, "12 bodies x 5 instants x 2 meridians");
}

/// Every horizon anchor point lies within the gate of the crate's curve.
#[test]
fn horizon_curves_match_the_swisseph_anchors() {
    if std::env::var_os(DATA_DIR_ENV).is_none() {
        eprintln!("skipping: {DATA_DIR_ENV} is unset, so the real kernels are not available");
        return;
    }
    let table: AnchorTable = serde_json::from_str(FIXTURE_JSON).expect("table parses");
    let loaded = loaded_with_kernels();
    let mut checked = 0;
    let mut worst = 0.0_f64;
    for row in &table.rows {
        let utc = epoch_from_label(&row.label);
        let lines = lines_for(&loaded, utc).expect("lines for fixture instant");
        for (angle, anchors) in [(Angle::Asc, &row.asc), (Angle::Dsc, &row.dsc)] {
            let line = line_of(&lines, &row.body, angle);
            let sampled = line
                .points
                .iter()
                .map(|point| [point.0, point.1])
                .collect::<Vec<[f64; 2]>>();
            for &[lon, lat] in anchors {
                let distance = distance_to_polyline_degrees(lon, lat, &sampled);
                worst = worst.max(distance);
                assert!(
                    distance <= GATE_DEG,
                    "{} for {} at {}: anchor ({lon:.9}, {lat:.9}) is {distance:.9}° from \
                     the crate's curve, > {GATE_DEG}°",
                    angle.name(),
                    row.body,
                    row.label
                );
                checked += 1;
            }
        }
    }
    eprintln!("checked {checked} anchors; worst deviation {worst:.6}°");
    assert!(checked >= 2300, "checked {checked} anchor points");
}

#[cfg(test)]
mod geometry_helpers {
    use super::*;

    /// The point-to-segment distance helper measures known offsets correctly.
    #[test]
    fn distance_to_segment_measures_known_offsets() {
        // One degree east of the prime meridian segment.
        let distance = distance_to_segment_degrees(
            unit_vector(1.0, 0.0),
            unit_vector(0.0, -30.0),
            unit_vector(0.0, 30.0),
        );
        assert!((distance - 1.0).abs() < 1e-9);

        // A point beyond the segment's end measures to that endpoint, not
        // the plane: 35° south of the arc (0°,0)-(0°,10).
        let distance = distance_to_segment_degrees(
            unit_vector(0.0, -35.0),
            unit_vector(0.0, 0.0),
            unit_vector(0.0, 10.0),
        );
        assert!((distance - 35.0).abs() < 1e-9, "got {distance}");
    }
}
